insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-06','verbeterd','Dossiers','Vanuit het dossier doorklikken naar de relatie',
   'Klik in een dossier op de naam van de opdrachtgever of de contactpersoon en je gaat meteen naar hun relatiegegevens, waar je alles kunt aanpassen en aanvullen. Dat kan vanaf de naam bovenaan het dossier en vanuit de blokken Projectinformatie en Opdrachtgever op het tabblad Informatie.');
